item.content:encoded:
.light-purple-label .fl-heading-text {
	background: #C5ADE4;
	padding: 3px 15px;
}

.section-home-hero {
	position: relative;
}

.section-home-hero:before {
	background: rgb(0,0,0);
	background: linear-gradient(0deg, rgba(0,0,0,1) 0%, rgba(255,255,255,1) 100%);
	content: '';
	display: block;
	position: absolute;
	top: 0;
	left: 0;
	width: 100%;
	height: 100%;
	z-index: 2;
	opacity: .4;
	background: rgb(0,0,0);
	background: linear-gradient(0deg, rgba(0,0,0,1) 0%, rgba(255,255,255,0) 100%);
}

.section-home-hero .fl-row-content {
	position: relative;
	z-index: 3;
}

.section-our-mission {
	position: relative;
}

@media (min-width: 768px) {
	.section-our-mission:after {
		content: '';
		position: absolute;
		top: 0;
		right: 0;
		background: url('https://www.austinballrz.com/wp-content/uploads/2023/07/baseball-seam-right.svg') no-repeat center;
		background-size: contain;
		width: 135px;
		height: 240px;
	}

	.section-our-mission:before {
		content: '';
		position: absolute;
		bottom: 0;
		left: 0;
		background: url('https://www.austinballrz.com/wp-content/uploads/2023/07/baseball-seam-left.svg') no-repeat center;
		background-size: contain;
		width: 135px;
    height: 250px;
    z-index: 1;
	}
}

